<script setup lang="ts">
definePageMeta({ role: 'admin', layout: 'admin' })

type VideoRow = { id: string; title: string; youtubeUrl: string; isActive: boolean; createdAt: string }
const modalOpen = ref(false)
const editMode = ref<'create' | 'edit'>('create')
const activeId = ref('')
const search = ref('')
const saving = ref(false)
const deletingId = ref('')
const errorMessage = ref('')
const successMessage = ref('')
const form = reactive({ title: '', youtubeUrl: '', isActive: true })
const { data, pending, error, refresh } = await useFetch('/api/admin/monitor-videos')
const rows = computed(() => (data.value?.data ?? []) as VideoRow[])
const filteredRows = computed(() => rows.value.filter((row) => `${row.title} ${row.youtubeUrl}`.toLowerCase().includes(search.value.toLowerCase())))
function resetFeedback(){ errorMessage.value=''; successMessage.value='' }
function validateForm(){ if(!form.title.trim()) return 'Judul video wajib diisi'; if(!form.youtubeUrl.trim()) return 'URL YouTube wajib diisi'; return '' }
function resetForm(){ Object.assign(form,{ title:'', youtubeUrl:'', isActive:true }); activeId.value=''; editMode.value='create' }
function openCreate(){ resetFeedback(); resetForm(); modalOpen.value=true }
function openEdit(row: VideoRow){ resetFeedback(); editMode.value='edit'; activeId.value=row.id; Object.assign(form,{ title:row.title, youtubeUrl:row.youtubeUrl, isActive:row.isActive }); modalOpen.value=true }
function getYoutubeEmbed(url: string){ const match = url.match(/(?:v=|youtu\.be\/|embed\/)([^?&/]+)/); const videoId = match?.[1]; return videoId ? `https://www.youtube-nocookie.com/embed/${videoId}` : '' }
async function handleSubmit(){ resetFeedback(); const validationError=validateForm(); if(validationError) return errorMessage.value=validationError; saving.value=true; try { if(editMode.value==='edit'&&activeId.value){ await $fetch(`/api/admin/monitor-videos/${activeId.value}`, { method:'PATCH', body:{ title:form.title.trim(), youtubeUrl:form.youtubeUrl.trim(), isActive:form.isActive } }); successMessage.value='Video berhasil diperbarui' } else { await $fetch('/api/admin/monitor-videos', { method:'POST', body:{ title:form.title.trim(), youtubeUrl:form.youtubeUrl.trim(), isActive:form.isActive } }); successMessage.value='Video berhasil ditambahkan' } modalOpen.value=false; resetForm(); await refresh() } catch (error:any) { errorMessage.value=error?.data?.statusMessage || error?.message || 'Gagal menyimpan video' } finally { saving.value=false } }
async function handleDelete(row: VideoRow){ resetFeedback(); deletingId.value=row.id; try { await $fetch(`/api/admin/monitor-videos/${row.id}`, { method:'DELETE' }); successMessage.value=`Video ${row.title} dinonaktifkan`; await refresh() } catch (error:any) { errorMessage.value=error?.data?.statusMessage || error?.message || 'Gagal menghapus video' } finally { deletingId.value='' } }
</script>
<template><div class="admin-page"><div class="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div><h1 class="text-4xl font-semibold tracking-tight">Manajemen Video Edukasi</h1><p class="mt-2 text-lg text-muted">Kelola playlist monitor dari backend admin.</p></div><div class="flex flex-col gap-3 sm:flex-row"><UInput v-model="search" icon="i-lucide-search" placeholder="Cari video..." class="sm:w-72" /><UButton label="Muat Ulang" icon="i-lucide-refresh-cw" color="neutral" variant="outline" :loading="pending" @click="refresh" /><UButton label="Tambah Video" icon="i-lucide-plus" color="primary" @click="openCreate" /></div></div><UPageCard v-if="successMessage" class="admin-table-card border border-success/30"><p class="font-semibold text-success">{{ successMessage }}</p></UPageCard><UPageCard v-if="error || errorMessage" class="admin-table-card border border-error/30"><p class="font-semibold text-error">{{ errorMessage || 'Gagal memuat video edukasi.' }}</p></UPageCard><div class="grid gap-6 xl:grid-cols-3"><UPageCard v-for="row in filteredRows" :key="row.id" class="overflow-hidden"><div class="space-y-4"><div class="relative aspect-video overflow-hidden rounded-2xl bg-elevated/40"><iframe v-if="getYoutubeEmbed(row.youtubeUrl)" :src="getYoutubeEmbed(row.youtubeUrl)" class="h-full w-full" title="Preview video edukasi" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen /><div v-else class="flex h-full items-center justify-center text-sm text-muted">Preview tidak tersedia</div></div><div class="grid gap-3 text-sm sm:grid-cols-2"><div class="rounded-2xl border border-default bg-elevated/30 p-3"><p class="text-[11px] font-semibold uppercase tracking-[0.08em] text-muted">Platform</p><p class="mt-1 font-medium">YouTube</p></div><div class="rounded-2xl border border-default bg-elevated/30 p-3"><p class="text-[11px] font-semibold uppercase tracking-[0.08em] text-muted">Status</p><UBadge class="mt-2" :color="row.isActive ? 'success' : 'neutral'" variant="subtle">{{ row.isActive ? 'Aktif' : 'Nonaktif' }}</UBadge></div><div class="rounded-2xl border border-default bg-elevated/30 p-3 sm:col-span-2"><p class="text-[11px] font-semibold uppercase tracking-[0.08em] text-muted">Judul</p><h3 class="mt-1 text-lg font-semibold leading-tight">{{ row.title }}</h3></div><div class="rounded-2xl border border-default bg-elevated/30 p-3 sm:col-span-2"><p class="text-[11px] font-semibold uppercase tracking-[0.08em] text-muted">Ditambahkan</p><p class="mt-1 text-sm text-muted">{{ new Date(row.createdAt).toLocaleDateString('id-ID') }}</p></div></div><div class="flex flex-col gap-3 border-t border-default pt-4 sm:flex-row sm:justify-end"><UButton icon="i-lucide-pencil" color="neutral" variant="ghost" @click="openEdit(row)">Edit</UButton><UButton icon="i-lucide-trash-2" color="error" variant="ghost" :loading="deletingId === row.id" @click="handleDelete(row)">Hapus</UButton></div></div></UPageCard></div><UModal v-model:open="modalOpen" :title="editMode === 'edit' ? 'Edit Video' : 'Tambah Video'"><template #body><div class="space-y-4"><div v-if="errorMessage" class="rounded-2xl border border-error/30 bg-error/5 px-4 py-3 text-sm text-error">{{ errorMessage }}</div><div class="grid gap-4 md:grid-cols-2"><UFormField class="md:col-span-2" label="Judul" required><UInput v-model="form.title" /></UFormField><UFormField class="md:col-span-2" label="URL YouTube" required><UInput v-model="form.youtubeUrl" /></UFormField><UFormField label="Status"><USelectMenu v-model="form.isActive" :items="[{ label: 'Aktif', value: true }, { label: 'Nonaktif', value: false }]" value-key="value" option-attribute="label" /></UFormField></div></div></template><template #footer><div class="flex flex-col-reverse gap-3 sm:flex-row sm:justify-end"><UButton label="Batal" color="neutral" variant="ghost" @click="modalOpen = false" /><UButton :label="editMode === 'edit' ? 'Update' : 'Simpan'" icon="i-lucide-save" :loading="saving" @click="handleSubmit" /></div></template></UModal></div></template>
